128	    @Transactional
129	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
130	            String corrects, String ref, List<String> tags) {
131	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
132	        if (claim.getStatus() != ClaimStatus.DRAFT) {
133	            throw new ClaimNotDraftException(claim.getStatus());
134	        }
135	        refuseLocked(claim, user);
136	        LocalDate on = date != null ? date : sheets.today(sheetId);
137	        refuseClosed(sheetId, claim.getDueBy());
138	        refuseRetired(people.findByIdAndSheetId(claim.getPersonId(), sheetId)
139	                .orElseThrow(PersonNotFoundException::new), on);
140	        refuseCorrection(sheetId, claim.getPersonId(), amount, corrects);
141	        refuseRefUsed(sheetId, ref, claim.getId());
142	        Rollup.Snapshot before = rollup.take(sheetId);
143	        claim.setAmount(amount.setScale(2));
144	        claim.setDate(on);
145	        claim.setNote(note);
146	        claim.setCorrects(corrects);
147	        claim.setRef(ref);
148	        claim.setTags(tags);
149	        claim.setLockedBy(null);
150	        claim.setEditedBy(user);
151	        Claim updated = claims.saveAndFlush(claim);
152	        Person person = people.findByIdAndSheetId(updated.getPersonId(), sheetId)
153	                .orElseThrow(PersonNotFoundException::new);
154	        audit("CLAIM_EDITED", updated, person, user);
155	        recordTags(sheetId, tags);
156	        rollup.recordChanges(sheetId, user, before);
157	        return updated;
158	    }
