205	    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to, String voidReason) {
206	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
207	        refuseClosed(sheetId, claim.getDueBy());
208	        roles.require(sheetId, user, switch (to) {
209	            case OPEN -> "open";
210	            case SETTLED, PENDING -> "settle";
211	            case VOID -> "void";
212	            case DRAFT -> throw new IllegalStateException();
213	        });
214	        if (!claim.getStatus().canBecome(to)) {
215	            throw new ClaimStatusException(claim.getStatus(), to);
216	        }
217	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
218	            refuseVoidSettled(claim, sheetId, user);
219	        }
220	        if (to == ClaimStatus.VOID) {
221	            refuseVoidReason(sheetId, voidReason);
222	        }
223	        String reversed = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED
224	                ? " reversed=" + show(claim.getSettledDue()) : "";
225	        if (to == ClaimStatus.VOID && !voidReason.isEmpty()) {
226	            reversed += " reason=" + voidReason;
227	        }
228	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
229	            throw new ClaimSettlerException("The user who opened a claim cannot settle it.");
230	        }
231	        if (to == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
232	            throw new ClaimSettlerException("The user who last edited a claim cannot settle it.");
233	        }
234	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
235	            throw new ClaimDeferException("The claim is deferred until " + claim.getDeferredUntil() + ".");
236	        }
237	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
238	                .orElseThrow(PersonNotFoundException::new);
239	        if (to == ClaimStatus.OPEN) {
240	            refuseNoteless(claim, shownDue(claim, person));
241	        }
242	        Rollup.Snapshot before = rollup.take(sheetId);
243	        String number = claim.getNumber();
244	        if (to == ClaimStatus.OPEN) {
245	            number = sheets.nextClaimNumber(sheetId, claim.getDueBy());
246	            claim.setOpenedBy(user);
247	        }
248	        if (to == ClaimStatus.SETTLED) {
249	            BigDecimal figure = claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
250	            BigDecimal due = figure == null ? null : charged(claim, person, figure);
251	            refuseUnproved(claim, person, due);
252	            if (overLimit(sheetId, user, due)) {
253	                to = ClaimStatus.PENDING;
254	            } else {
255	                claim.setSettledDue(due);
256	            }
257	        }
258	        claim.setStatus(to);
259	        claim.setNumber(number);
260	        if (to == ClaimStatus.VOID) {
261	            claim.setVoidReason(voidReason.isEmpty() ? null : voidReason);
262	        }
263	        logStatus(claim, person, user);
264	        Claim updated = claims.saveAndFlush(claim);
265	        String event = switch (to) {
266	            case OPEN -> "CLAIM_OPENED";
267	            case PENDING -> "CLAIM_PENDING";
268	            case SETTLED -> "CLAIM_SETTLED";
269	            case VOID -> "CLAIM_VOIDED";
270	            case DRAFT -> throw new IllegalStateException();
271	        };
272	        audit(event, updated, person, user, number, to == ClaimStatus.SETTLED ? dueField(updated) : reversed);
273	        if (to == ClaimStatus.SETTLED) {
274	            notifyWatchers(updated, person, user);
275	        }
276	        rollup.recordChanges(sheetId, user, before);
277	        return updated;
278	    }
