280	    /** Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure now, its late charge on
281	     *  the sheet's today frozen in on top (with no figure then, its due stays live). Refused unless the
282	     *  claim is PENDING and the user is a steward other than the one who opened it or last edited it. */
283	    @Transactional
284	    public Claim approve(String sheetId, String user, long claimId) {
285	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
286	        refuseClosed(sheetId, claim.getDueBy());
287	        if (claim.getStatus() != ClaimStatus.PENDING) {
288	            throw new ClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
289	        }
290	        if (!roles.isSteward(sheetId, user)) {
291	            throw new ClaimApprovalException("Only a steward can approve a claim.");
292	        }
293	        if (user.equals(claim.getOpenedBy())) {
294	            throw new ClaimApprovalException("The user who opened a claim cannot approve it.");
295	        }
296	        if (user.equals(claim.getEditedBy())) {
297	            throw new ClaimApprovalException("The user who last edited a claim cannot approve it.");
298	        }
299	        Rollup.Snapshot before = rollup.take(sheetId);
300	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
301	                .orElseThrow(PersonNotFoundException::new);
302	        BigDecimal figure = liveDue(claim, person);
303	        BigDecimal due = figure == null ? null : charged(claim, person, figure);
304	        refuseUnproved(claim, person, due);
305	        claim.setSettledDue(due);
306	        claim.setStatus(ClaimStatus.SETTLED);
307	        logStatus(claim, person, user);
308	        Claim updated = claims.saveAndFlush(claim);
309	        audit("CLAIM_APPROVED", updated, person, user, updated.getNumber(), dueField(updated));
310	        notifyWatchers(updated, person, user);
311	        rollup.recordChanges(sheetId, user, before);
312	        return updated;
313	    }
