370	    /** Re-settle a SETTLED claim: freeze it again at the figure it would have today as an OPEN claim bound by
371	     *  no statement (today's rates, grades and floor, the late charge on the sheet's today on top). Refused
372	     *  unless the claim is SETTLED and the user is a steward, and for a claim in a closed period. */
373	    @Transactional
374	    public Claim resettle(String sheetId, String user, long claimId) {
375	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
376	        refuseClosed(sheetId, claim.getDueBy());
377	        if (!roles.isSteward(sheetId, user)) {
378	            throw new ClaimResettleException("Only a steward can re-settle a claim.");
379	        }
380	        if (claim.getStatus() != ClaimStatus.SETTLED) {
381	            throw new ClaimResettleException("Only a SETTLED claim can be re-settled.");
382	        }
383	        Rollup.Snapshot before = rollup.take(sheetId);
384	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
385	                .orElseThrow(PersonNotFoundException::new);
386	        BigDecimal old = claim.getSettledDue();
387	        BigDecimal figure = liveDue(claim, person);
388	        BigDecimal due = null;
389	        if (figure != null) {
390	            Sheet sheet = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new);
391	            LocalDate lateFrom = sheet.lateFrom(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate());
392	            due = claim.isCorrection() ? figure
393	                    : sheet.floored(figure.add(sheet.lateCharge(figure, lateFrom, claim.getDate())), claim.getDate());
394	        }
395	        claim.setSettledDue(due);
396	        logStatus(claim, person, user);
397	        Claim updated = claims.saveAndFlush(claim);
398	        audit("CLAIM_RESETTLED", updated, person, user, updated.getNumber(),
399	                " old=" + show(old) + " new=" + show(due));
400	        notifyWatchers(updated, person, user);
401	        rollup.recordChanges(sheetId, user, before);
402	        return updated;
403	    }
