493	    /** Move a claim as a reassign does; one already the person's is refused only when {@code refuseOwn}. */
494	    private Claim move(String sheetId, String user, long claimId, long toPersonId, boolean refuseOwn) {
495	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
496	        refuseClosed(sheetId, claim.getDueBy());
497	        if (!roles.allows(sheetId, user, "reassign")) {
498	            throw new ClaimReassignException("Your role may not reassign a claim.");
499	        }
500	        if (!claim.getStatus().canMove()) {
501	            throw new ClaimReassignException("A " + claim.getStatus() + " claim cannot be reassigned.");
502	        }
503	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
504	                .orElseThrow(PersonNotFoundException::new);
505	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
506	        if (refuseOwn && from.getId().equals(to.getId())) {
507	            throw new ClaimReassignException("The claim is already " + to.getName() + "'s.");
508	        }
509	        refuseRetired(to, claim.getDate());
510	        Rollup.Snapshot before = rollup.take(sheetId);
511	        claim.setPersonId(to.getId());
512	        claim.setStated(false, null);
513	        if (claim.getNumber() != null) {
514	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
515	        }
516	        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
517	        Claim updated = claims.saveAndFlush(claim);
518	        audit("CLAIM_REASSIGNED", updated, to, user, updated.getNumber(),
519	                " from=" + from.getName() + " to=" + to.getName());
520	        rollup.recordChanges(sheetId, user, before);
521	        return updated;
522	    }
