528	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and loses any figure a
529	     *  statement bound it to; a new OPEN claim of the person with the amount split off, the same date and
530	     *  note, the next number, opened by the user and due by the terms-th business day after its date (by the terms in
531	     *  force on it and the sheet's holidays), is
532	     *  listed as the sheet's newest, naming the original's number as split from. Refused unless the user's
533	     *  role may open a claim, the claim is OPEN and not deferred, and the amount is above 0.00 and below the
534	     *  claim's; and for a claim in a closed period. */
535	    @Transactional
536	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
537	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
538	        refuseClosed(sheetId, claim.getDueBy());
539	        roles.require(sheetId, user, "open");
540	        if (claim.getStatus() != ClaimStatus.OPEN) {
541	            throw new ClaimSplitException("Only an OPEN claim can be split.");
542	        }
543	        LocalDate today = sheets.today(sheetId);
544	        if (claim.deferredOn(today)) {
545	            throw new ClaimSplitException("The claim is deferred until " + claim.getDeferredUntil() + ".");
546	        }
547	        BigDecimal part = amount.setScale(2);
548	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
549	            throw new ClaimSplitException("Split off more than 0.00 and less than the claim's amount.");
550	        }
551	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
552	                .orElseThrow(PersonNotFoundException::new);
553	        Rollup.Snapshot before = rollup.take(sheetId);
554	        claim.setAmount(claim.getAmount().subtract(part));
555	        claim.setStated(false, null);
556	        Claim kept = claims.saveAndFlush(claim);
557	        int terms = person.getTerms() != null ? person.getTerms()
558	                : sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
559	                        .termsFor(person.gradeOn(claim.getDate()), claim.getDate());
560	        Claim split = new Claim(sheetId, person.getId(), part, claim.getDate(),
561	                holidays.businessDaysAfter(sheetId, claim.getDate(), terms),
562	                claim.getNote(), null);
563	        split.setTerms(terms);
564	        split.setListOrder(claims.maxListOrder(sheetId) + 1);
565	        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
566	        split.setStatus(ClaimStatus.OPEN);
567	        split.setNumber(sheets.nextClaimNumber(sheetId, split.getDueBy()));
568	        split.setOpenedBy(user);
569	        split.setSplitFrom(claim.getNumber());
570	        split.setTags(claim.getTags());
571	        logStatus(split, person, user);
572	        split = claims.saveAndFlush(split);
573	        audit("CLAIM_SPLIT", kept, person, user, kept.getNumber(), " into=" + split.getNumber());
574	        audit("CLAIM_OPENED", split, person, user);
575	        rollup.recordChanges(sheetId, user, before);
576	        return new Split(kept, split);
577	    }
