583	    /** Open the chosen claims together, numbering them in list order (people in the order they were added,
584	     *  each person's claims newest first); a claim that cannot be opened is left as it is and counted as
585	     *  refused, as is one not on the sheet. */
586	    @Transactional
587	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> claimIds) {
588	        Set<Long> chosen = new HashSet<>(claimIds);
589	        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
590	            return new BulkOpened(0, chosen.size(), List.of());
591	        }
592	        List<Claim> opened = new ArrayList<>();
593	        for (Claim claim : inListOrder(sheetId, chosen)) {
594	            try {
595	                opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
596	            } catch (ClaimStatusException | PeriodClosedException | ClaimNotFoundException
597	                    | ActionNotAllowedException | ClaimNoteException e) {
598	                // refused: left as it is
599	            }
600	        }
601	        return new BulkOpened(opened.size(), chosen.size() - opened.size(), opened);
602	    }
