604	    /** What a bulk settle did: how many it settled (PENDING included) and refused, the claims it changed, and
605	     *  the number of the batch it made (none when it settled none). */
606	    public record BulkSettled(int settled, int refused, List<Claim> claims, Integer batch) {
607	    }
608	
609	    /** Settle the chosen claims together in list order (people in the order they were added, each person's
610	     *  claims newest first), each as a single settle by the user would; one a clerk puts PENDING counts as
611	     *  settled. All or nothing: if any one cannot be settled (or is not on the sheet), none is, every one
612	     *  counts as refused and nothing is written. Otherwise they are the sheet's next batch, each claim taking
613	     *  its number, and BATCH_SETTLED follows the claims' own lines with the frozen figures of those SETTLED
614	     *  added up. */
615	    @Transactional
616	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> claimIds) {
617	        Set<Long> chosen = new HashSet<>(claimIds);
618	        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
619	            return new BulkSettled(0, chosen.size(), List.of(), null);
620	        }
621	        List<Claim> found = inListOrder(sheetId, chosen);
622	        if (found.size() != chosen.size()) {
623	            return new BulkSettled(0, chosen.size(), List.of(), null);
624	        }
625	        List<Claim> settled = new ArrayList<>();
626	        for (Claim claim : found) {
627	            try {
628	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
629	            } catch (ClaimStatusException | ClaimSettlerException | ClaimDeferException | ClaimProofException
630	                    | PeriodClosedException | ActionNotAllowedException
631	                    | ClaimNotFoundException e) {
632	                // refused: undo every settle made so far, and write none of their lines
633	                TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
634	                return new BulkSettled(0, chosen.size(), List.of(), null);
635	            }
636	        }
637	        Integer batch = null;
638	        if (!settled.isEmpty()) {
639	            batch = sheets.nextSettleBatch(sheetId);
640	            BigDecimal total = BigDecimal.ZERO.setScale(2);
641	            for (Claim claim : settled) {
642	                claim.setSettleBatch(batch);
643	                if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
644	                    total = total.add(claim.getSettledDue());
645	                }
646	            }
647	            settled = claims.saveAllAndFlush(settled);
648	            audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
649	                    + " count=" + settled.size() + " total=" + total.toPlainString());
650	        }
651	        return new BulkSettled(settled.size(), 0, settled, batch);
652	    }
