679	    /** The sheet's chosen claims in list order: people in the order they were added, each person's claims
680	     *  newest first. */
681	    private List<Claim> inListOrder(String sheetId, Set<Long> chosen) {
682	        Map<Long, Integer> personOrder = new HashMap<>();
683	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
