692	    /** A person, their statements in the order taken, and their claims newest first. */
693	    public record Stated(Person person, List<Statement> statements, List<Claim> claims) {
694	    }
695	
696	    /** Take a person's statement: record their due-total now (late charges included) and how many claims
697	     *  count, and bind each claim that counts to its rate figure now, under its late charge and floor (the charge is
698	     *  never bound: it keeps following the sheet's today, and the floor is applied on top; a PENDING claim is bound only once it is back to
699	     *  OPEN); a claim that does not count, is OPEN or PENDING and dated within one of its person's holds (or its person's retirement date is reached), or is
700	     *  deferred past the sheet's today, is left unbound. */
701	    @Transactional
702	    public Stated statement(String sheetId, String user, long personId) {
703	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
704	        LocalDate today = sheets.today(sheetId);
705	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
706	        Rollup.Snapshot before = rollup.take(sheetId);
707	        BigDecimal total = BigDecimal.ZERO.setScale(2);
708	        boolean figure = false;
709	        int counted = 0;
710	        for (Claim claim : theirs) {
711	            if (!claim.getStatus().counts() || (claim.getStatus().isOpen() && (person.heldOn(claim.getDate()) || person.retiredBy(today)))
712	                    || claim.deferredOn(today)) {
713	                claim.setStated(false, null);
714	                continue;
715	            }
716	            BigDecimal due = due(claim, person);
717	            if (due != null) {
718	                total = total.add(charged(claim, person, due));
719	                figure = true;
720	            }
721	            claim.setStated(true, due);
722	            counted++;
723	        }
724	        boolean rated = Rollup.inForce(rates.findWithAncestors(sheetId, sheetRows.ancestors(sheetId)), person.gradeOn(today), today).isPresent();
725	        BigDecimal summed = total;
726	        BigDecimal dueTotal = rated || figure
727	                ? sheetRows.findById(sheetId).map(s -> s.capped(summed)).orElse(summed) : null;
728	        claims.saveAllAndFlush(theirs);
729	        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
730	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
731	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
732	        rollup.recordChanges(sheetId, user, before);
733	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
734	    }
735	
736	    /** Take a person's statement as of a date on or before the sheet's today: the claims of theirs that
737	     *  counted at the end of that date (as the changes made while the sheet's today was on or before it left
738	     *  them; a later change does not count) are bound to their figures as they stood then, that date standing
739	     *  in for the sheet's today in every figure (the grade and rate in force, the floor, late charges, holds,
740	     *  retirements and the cap); every other claim of theirs is left unbound. The statement is dated that
741	     *  date. Refused for a date after the sheet's today, and one before the person was on the sheet. */
742	    @Transactional
743	    public Stated statementAsOf(String sheetId, String user, long personId, LocalDate asOf) {
744	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
745	        LocalDate today = sheets.today(sheetId);
746	        if (asOf.isAfter(today)) {
747	            throw new StatementRefusedException("A statement cannot be taken as of a date after the sheet's today ("
748	                    + today + ").");
749	        }
750	        Person then = history.findAsOf(Person.class, sheetId, personId, asOf)
751	                .orElseThrow(() -> new StatementRefusedException(person.getName() + " was not on the sheet on " + asOf + "."));
752	        Sheet sheetThen = history.findAsOf(Sheet.class, sheetId, sheetId, asOf).orElseGet(() -> {
753	            // no change to the sheet counts by then: it stands as it was started
754	            Sheet now = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new);
755	            return new Sheet(sheetId, now.getCreatedBy(), now.getCreatedAt(), asOf);
756	        });
757	        sheetThen.setToday(asOf);
758	        Optional<Sheet> onDate = Optional.of(sheetThen);
759	        List<Rate> ratesThen = new ArrayList<>(history.listAsOf(Rate.class, sheetId, asOf));
760	        sheetRows.ancestors(sheetId).forEach(a -> ratesThen.addAll(history.listAsOf(Rate.class, a, asOf)));
761	        List<Claim> claimsThen = history.listAsOf(Claim.class, sheetId, asOf).stream()
762	                .filter(c -> c.getPersonId().equals(personId)).toList();
763	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
764	        Rollup.Snapshot before = rollup.take(sheetId);
765	        Map<Long, BigDecimal> figures = new HashMap<>();
766	        BigDecimal total = BigDecimal.ZERO.setScale(2);
767	        boolean figure = false;
768	        for (Claim claim : claimsThen) {
769	            if (!claim.getStatus().counts() || Rollup.heldOut(claim, then, asOf) || claim.deferredOn(asOf)) {
770	                continue;
771	            }
772	            BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
773	                    : claim.isBound() ? claim.getStatedDue()
774	                    : Rollup.inForce(ratesThen, then.gradeOn(claim.getDate()), claim.getDate())
775	                            .map(rate -> Rollup.rated(onDate, claim, claimsThen, rate)).orElse(null);
776	            if (due != null) {
777	                total = total.add(Rollup.charged(onDate, claim, then, due));
778	                figure = true;
779	            }
780	            figures.put(claim.getId(), due);
781	        }
782	        for (Claim claim : theirs) {
783	            claim.setStated(figures.containsKey(claim.getId()), figures.get(claim.getId()));
784	        }
785	        boolean rated = Rollup.inForce(ratesThen, then.gradeOn(asOf), asOf).isPresent();
786	        BigDecimal dueTotal = rated || figure ? sheetThen.capped(total) : null;
787	        int counted = figures.size();
788	        claims.saveAllAndFlush(theirs);
789	        statements.saveAndFlush(new Statement(sheetId, personId, asOf, dueTotal, counted));
790	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
791	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted
792	                + " asof=" + asOf);
793	        rollup.recordChanges(sheetId, user, before);
794	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
795	    }
