797	    /** Cancel a person's last statement: the claims it bound are live again (a figure an earlier statement
798	     *  bound is not restored), and the statement before it becomes their last. Refused unless the user is a
799	     *  steward and the person has a statement. */
800	    @Transactional
801	    public Stated cancelStatement(String sheetId, String user, long personId) {
802	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
803	        if (!roles.isSteward(sheetId, user)) {
804	            throw new StatementCancelException("Only a steward can cancel a statement.");
805	        }
806	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
807	        List<Statement> taken = statements.findByPersonIdOrderByIdAsc(personId);
808	        if (taken.isEmpty()) {
809	            throw new StatementCancelException(person.getName() + " has no statement to cancel.");
810	        }
811	        Statement last = taken.get(taken.size() - 1);
812	        Rollup.Snapshot before = rollup.take(sheetId);
813	        for (Claim claim : theirs) {
814	            claim.setStated(false, null);
815	        }
816	        claims.saveAllAndFlush(theirs);
817	        statements.delete(last);
818	        statements.flush();
819	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
820	                + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString()));
821	        rollup.recordChanges(sheetId, user, before);
822	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
823	    }
