984	    /** The claim's rate figure: its amount at the rate in force on its date of its person's grade in force
985	     *  then, before any late charge or floor; none when no rate applies. */
986	    private BigDecimal liveDue(Claim claim, Person person) {
987	        Sheet sheet = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new);
988	        RoundingMode rounding = sheet.rounding(roundingDate(claim));
989	        return Rollup.inForce(rates.findWithAncestors(claim.getSheetId(), sheetRows.ancestors(claim.getSheetId())),
990	                        person.gradeOn(claim.getDate()), claim.getDate())
991	                .map(rate -> due(claim.getAmount(), rate, rounding))
992	                .orElse(null);
993	    }
