995	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it corrects. */
996	    private LocalDate roundingDate(Claim claim) {
997	        if (!claim.isCorrection()) {
998	            return claim.getDate();
999	        }
1000	        return claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
1001	                .map(Claim::getDate).orElse(claim.getDate());
