1020	    private void notifyWatchers(Claim claim, Person person, String user) {
1021	        for (Watch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
1022	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUser()
1023	                    + " person=" + person.getName() + " number=" + claim.getNumber());
1024	        }
1025	    }
1026	
1027	    /** The amount as the screen shows it (two decimals), the date YYYY-MM-DD. */
1028	    private void audit(String event, Claim claim, Person person, String user) {
1029	        audit(event, claim, person, user, claim.getNumber(), "");
1030	    }
1031	
1032	    /** A claim with a number (a voided claim keeps its own) follows its date with number=, then any extra fields. */
1033	    private void audit(String event, Claim claim, Person person, String user, String number, String extra) {
1034	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
1035	                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
1036	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
1037	    }
