          <button type="button" data-testid="claim-inline-save" [disabled]="acting() === c.id" (click)="saveInline(c)">
            Save amount<span class="visually-hidden"> of claim {{ c.amount }} on {{ c.date }}</span>
          </button>
          @if (voidReasons.reasons().length > 0) {
