      <label [for]="fid('note')">Note</label>
      <input
        [id]="fid('note')"
        data-testid="claim-form-note"
        [value]="note()"
        (input)="note.set(value($event)); clearErrors()"
      />
      <label [for]="fid('corrects')">Corrects claim no. (for a negative amount)</label>
      <input
        [id]="fid('corrects')"
